/// <summary>
/// Extension of form <c>LogisticsPostalAddress</c> datasource <c>TaxRegistration</c>.
/// </summary>
[ExtensionOf(formDataSourceStr(LogisticsPostalAddress, TaxRegistration))]
final class METLogisticsPostalAddressFormTaxRegistrationDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Runs when datasouce record is activted.
    /// </summary>
    /// <returns>Is active.</returns>
    public int active()
    {
        int ret = next active();

        this.metEnableDatasourceFields();

        return ret;
    }

    /// <summary>
    /// CB756_ValidationOfABNToATOSystem.
    /// Enables and disables datasource <c>TaxRegistration</c> fields.
    /// </summary>
    private void metEnableDatasourceFields()
    {
        TaxRegistration taxRegistration;
        boolean         isVerifiedDateEmpty;

        taxRegistration = this.cursor();
        isVerifiedDateEmpty = (taxRegistration.METVerifiedDate == dateNull());

        this.object(fieldNum(TaxRegistration, Description)).allowEdit(isVerifiedDateEmpty);
        this.object(fieldNum(TaxRegistration, METStatus)).allowEdit(isVerifiedDateEmpty);
        this.object(fieldNum(TaxRegistration, Section)).allowEdit(isVerifiedDateEmpty);

        this.object(fieldNum(TaxRegistration, METVerifiedDate)).allowEdit(false);
    }
